<?php require_once __DIR__.'/../../app/layout.php';$m=require_member();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$amount=(float)$_POST['amount'];$txn=trim($_POST['transaction_no']??'');if($amount<=0||!in_array($_POST['payment_mode']??'',['upi','bank','cash'],true)||($txn!==''&&strlen($txn)<4))throw new RuntimeException('Enter valid payment details.');$pdo->prepare('INSERT INTO membership_payments (member_id,amount,payment_mode,transaction_no,payment_date,proof_path) VALUES (?,?,?,?,?,?)')->execute([$m['id'],$amount,$_POST['payment_mode'],$txn?:null,$_POST['payment_date'],upload('proof')]);flash('Payment submitted for administrator verification.');redirect('/member/dashboard.php');}catch(Throwable $e){flash($e->getMessage()==='SQLSTATE[23000]: Integrity constraint violation: 1062 Duplicate entry'?'This transaction number was already used.':$e->getMessage(),'error');}}header_html('Membership payment');?><h1>Membership payment</h1><p><?=e(setting($pdo,'membership_description'))?><br>UPI: <?=e(setting($pdo,'upi_id'))?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Amount<input type="number" step="0.01" min="1" name="amount" required value="<?=e(setting($pdo,'membership_fee'))?>"></label><label>Mode<select name="payment_mode"><option value="upi">UPI / QR</option><option value="bank">Bank transfer</option><option value="cash">Cash</option></select></label><label>UTR / Transaction Number<input name="transaction_no" maxlength="100"></label><label>Payment date<input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required></label><label>Proof (JPG, PNG, WEBP or PDF, max 5 MB)<input type="file" name="proof"></label><button>Submit for verification</button></form><?php footer_html();
